effect.shader:
float gmLum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float l = pow(clamp(gmLum(src.rgb), 0.0, 1.0), gammaC);
l = clamp((l - 0.5) * (1.0 + contrast * 0.02) + 0.5, 0.0, 1.0);
float s = max(mapSoft, 0.001);
vec3 col;
if (tritone) {
float m1 = smoothstep(0.5 - s, 0.5 + s, l);
vec3 lowHalf = mix(shadowCol.rgb, midCol.rgb, clamp(l / max(0.5 - s, 0.001), 0.0, 1.0));
vec3 highHalf = mix(midCol.rgb, highCol.rgb, clamp((l - 0.5 - s) / max(0.5 - s, 0.001), 0.0, 1.0));
col = mix(lowHalf, highHalf, m1);
} else {
col = mix(shadowCol.rgb, highCol.rgb, clamp(l, 0.0, 1.0));
}
float detail = gmLum(src.rgb) - gmLum(vec3(gmLum(src.rgb)));
col += detail * 60.0 * keepLumaDetail;
col = clamp(col, 0.0, 1.0);
gl_FragColor = vec4(mix(src.rgb, col, mixAmount * 0.01) * src.a, src.a);
}
